import sys

def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return sorted([seen[target - n], i])
        seen[n] = i

if __name__ == '__main__':
    data = sys.stdin.read().split('\n')
    nums = list(map(int, data[0].split()))
    target = int(data[1])
    a, b = two_sum(nums, target)
    print(a, b)

