import sys

def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    st = []
    for ch in s:
        if ch in '([{':
            st.append(ch)
        elif not st or st.pop() != pairs[ch]:
            return False
    return not st

s = sys.stdin.readline().rstrip('\n')
print('true' if is_valid(s) else 'false')

