import sys
from collections import deque

def ladder_length(begin, end, words):
    bank = set(words)
    if end not in bank:
        return 0
    q = deque([(begin, 1)])
    seen = {begin}
    while q:
        word, d = q.popleft()
        if word == end:
            return d
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nxt = word[:i] + c + word[i+1:]
                if nxt in bank and nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, d + 1))
    return 0

lines = sys.stdin.read().split('\n')
begin, end = lines[0], lines[1]
words = lines[2].split()
print(ladder_length(begin, end, words))
